"""sklearn.utils.multiclass — multiclass classification utilities."""

import numpy as _np


def type_of_target(y, input_name=''):
    """Classify the target type — 'continuous', 'binary', 'multiclass',
    'multilabel-indicator', 'continuous-multioutput', 'multiclass-multioutput'."""
    y = _np.asarray(y)
    if y.ndim == 0:
        return 'unknown'
    if y.dtype.kind == 'f':
        if y.ndim == 1:
            return 'continuous'
        return 'continuous-multioutput'
    if y.ndim == 1:
        unique = _np.unique(y)
        return 'binary' if len(unique) <= 2 else 'multiclass'
    # 2-D.
    if y.dtype.kind in 'bu' or set(_np.unique(y)) <= {0, 1}:
        return 'multilabel-indicator'
    return 'multiclass-multioutput'


def unique_labels(*ys):
    """Return the union of unique labels across all ``ys``."""
    seen = set()
    for y in ys:
        seen.update(_np.unique(_np.asarray(y)).tolist())
    return _np.array(sorted(seen))


def is_multilabel(y):
    """True if y has the shape of a multilabel-indicator matrix."""
    y = _np.asarray(y)
    if y.ndim != 2:
        return False
    return y.dtype.kind in 'bu' or set(_np.unique(y).tolist()) <= {0, 1}


def check_classification_targets(y):
    """Raise if y is not a classification target type."""
    t = type_of_target(y)
    if t not in ('binary', 'multiclass', 'multilabel-indicator',
                  'multiclass-multioutput'):
        raise ValueError(f'Unknown classification target type: {t}')


def class_distribution(y, sample_weight=None):
    """Per-column distribution of class labels in a 2-D ``y``."""
    y = _np.asarray(y)
    n_outputs = 1 if y.ndim == 1 else y.shape[1]
    classes, n_classes, prior = [], [], []
    for k in range(n_outputs):
        col = y if y.ndim == 1 else y[:, k]
        c, counts = _np.unique(col, return_counts=True)
        classes.append(c); n_classes.append(len(c))
        prior.append(counts.astype(float) / counts.sum())
    return classes, n_classes, prior
